template<typename RealType = double>
class student_t_distribution {
    RealType internal_n; // Degrees of freedom

    // Requires: 0 < n
    explicit student_t_distribution(const RealType& n = 1.0)
        : internal_n(n)
    {
        // Constraint enforced at runtime (not constexpr)
        if (n <= 0.0) {
            /* Throw implementation-defined error */
        }
    }

    RealType n() const { return internal_n; }
};
